proposed_assertion.definition:
-- Uniqueness assertion on user_dim
SELECT COUNT(*) AS duplicate_keys FROM (
  SELECT user_id
  FROM user_dim
  GROUP BY 1 HAVING COUNT(*) > 1
) HAVING COUNT(*) = 0;

